cd /Users/kvnkishore/WebstormProjects/AgenticEngineer/IndyDevDan/ah-6-building-agentic-layers/transcript
awk '
/^[0-9]{2}:[0-9]{2}:[0-9]{2}/ { ts=substr($1,1,8); next }
/^[0-9]+$/ { next }
/^WEBVTT/ { next }
NF { txt=txt" "$0; if(!s[ts]) {start[++k]=ts} tmap[ts]=tmap[ts]" "$0 }
END {
  # rebuild: iterate cues in order by reading file again is complex; instead print merged per 15s bucket
}
' ah-6-building-agentic-layers.vtt > /dev/null
# Simpler: pair each timestamp with following text lines until blank, output "ts | text"
awk '
BEGIN{ts=""}
/^[0-9]{2}:[0-9]{2}:[0-9]{2}/ {ts=substr($1,1,8); buf=""; next}
/^[0-9]+$/ {next}
/^WEBVTT/ {next}
/^[[:space:]]*$/ { if(ts!="" && buf!=""){print ts" |"buf; ts=""; buf=""} next}
{ buf=buf" "$0 }
END{ if(ts!="" && buf!="") print ts" |"buf }
' ah-6-building-agentic-layers.vtt > /tmp/ah6_flat.txt
wc -l /tmp/ah6_flat.txt
echo "=== sample ===" && sed -n '1,6p' /tmp/ah6_flat.txt

cd /Users/kvnkishore/WebstormProjects/AgenticEngineer/IndyDevDan/ah-6-building-agentic-layers/transcript
# Bucket cues into 12-second windows so phrases are searchable
awk -F' \\| ' '{
  split($1,t,":"); sec=t[1]*3600+t[2]*60+t[3]; b=int(sec/12)*12;
  if(b!=cur){ if(cur!=""){printf "%02d:%02d | %s\n", int(cur/60),cur%60,txt} cur=b; txt=""}
  txt=txt" "$2
} END{ if(cur!="") printf "%02d:%02d | %s\n", int(cur/60),cur%60,txt }' /tmp/ah6_flat.txt > /tmp/ah6_win.txt
wc -l /tmp/ah6_win.txt
echo "=== search key moments ==="
grep -niE "singularity|green square|orchestrator|expert|gift|one purpose|prioritize|reveal|highest leverage|log stream|swimlane|reset|start from zero" /tmp/ah6_win.txt | head -60
